export const LANGS = ["pt", "en", "es"];
const index = { pt: 0, en: 1, es: 2 };

export function translate(lang, key, params = {}) {
  const entry = M[key];
  let text = entry ? (entry[index[lang]] ?? entry[1] ?? entry[0]) : key;
  Object.entries(params).forEach(([name, value]) => { text = text.split(`{${name}}`).join(String(value)); });
  return text;
}

export function hasMessage(key) { return Boolean(M[key]); }

export function money(amount, lang) {
  if (amount === null || amount === undefined || Number.isNaN(Number(amount))) return null;
  return new Intl.NumberFormat({ pt: "pt-BR", en: "en-US", es: "es-US" }[lang] || "en-US", { style: "currency", currency: "USD", maximumFractionDigits: amount % 1 ? 2 : 0 }).format(amount);
}
